// ============================================================
// Filter: Nur Workflow-erstellte Events behalten
// ============================================================
// Erkennt Events anhand von:
// 1. [n8n-scouting]-Tag (neue Events)
// 2. "Wettbewerb:" UND "Gegner:" in der Beschreibung (alte Events)
// Manuelle Kalendereinträge bleiben unberührt!
// ============================================================

const items = $input.all();
const scoutingEvents = [];

for (const item of items) {
    const desc = (item.json.description || '').toString();
    const summary = (item.json.summary || '').toString();
    const eventId = item.json.id || item.json.eventId || '';

    if (!eventId) continue;

    // Prüfe ob Event vom Workflow erstellt wurde
    const hasNewTag = desc.includes('[n8n-scouting]');
    const hasOldFormat = desc.includes('Wettbewerb:') && desc.includes('Gegner:') && desc.includes('Academy-Spieler:');

    if (hasNewTag || hasOldFormat) {
        scoutingEvents.push({
            json: {
                eventId: eventId,
                summary: summary,
                description: desc
            }
        });
    }
}

// Wenn keine Scouting-Events vorhanden, leeres Signal senden
if (scoutingEvents.length === 0) {
    return [{ json: { no_events: true, eventId: '' } }];
}

return scoutingEvents;

// ============================================================
// fussball.de Match-Detail-Seite Parser v2
// ============================================================

try {
    const masterSpiele = $("Spielplan parsen").all();
    const httpAntworten = $input.all();
    const results = [];

    for (let i = 0; i < masterSpiele.length; i++) {
        let itemJson = JSON.parse(JSON.stringify(masterSpiele[i].json));
        let heimTeam = itemJson.titel ? itemJson.titel.split(' - ')[0].trim() : "Unbekannt";
        let finaleAdresse = heimTeam;

        try {
            const responseItem = httpAntworten[i];
            if (responseItem && itemJson.ortsangabe) {
                let html = "";
                if (responseItem.binary && responseItem.binary.data) {
                    html = Buffer.from(responseItem.binary.data.data, 'base64').toString('utf-8');
                } else {
                    html = responseItem.json.data || responseItem.json.body || "";
                }

                if (html) {
                    const mapsLinkRegex = /<a[^>]*href="https?:\/\/(?:www\.)?google\.[a-z]+\/maps\?q=[^"]*"[^>]*>([\s\S]*?)<\/a>/i;
                    const mapsMatch = html.match(mapsLinkRegex);
                    if (mapsMatch && mapsMatch[1]) {
                        let adressText = mapsMatch[1].replace(/<[^>]*>/g, '').trim();
                        if (adressText.length > 3) finaleAdresse = adressText;
                    }

                    if (finaleAdresse === heimTeam) {
                        const mapsUrlRegex = /google\.[a-z]+\/maps\?q=([^"&]+)/i;
                        const urlMatch = html.match(mapsUrlRegex);
                        if (urlMatch && urlMatch[1]) {
                            let decoded = decodeURIComponent(urlMatch[1].replace(/\+/g, ' ')).trim();
                            if (decoded.length > 3) finaleAdresse = decoded;
                        }
                    }

                    if (finaleAdresse === heimTeam) {
                        const venueRegex = /class="[^"]*venue[^"]*"[\s\S]*?<\/div>/i;
                        const venueMatch = html.match(venueRegex);
                        if (venueMatch) {
                            const addressInVenue = venueMatch[0].replace(/<[^>]*>/g, ' ').trim();
                            const plzMatch = addressInVenue.match(/(\d{5}\s+[A-Za-z\u00c4\u00d6\u00dc\u00e4\u00f6\u00fc\u00df]+)/);
                            if (plzMatch) finaleAdresse = addressInVenue.replace(/\s+/g, ' ').trim();
                        }
                    }
                }
            }
        } catch (e) {}

        itemJson.stadion_adresse = finaleAdresse;
        delete itemJson.data;
        delete itemJson.body;
        results.push({ json: itemJson, pairedItem: { item: i } });
    }

    return results;
} catch (error) {
    const masterSpiele = $("Spielplan parsen").all();
    return masterSpiele.map((item, i) => {
        const j = JSON.parse(JSON.stringify(item.json));
        j.stadion_adresse = j.titel ? j.titel.split(' - ')[0].trim() : "Unbekannt";
        return { json: j, pairedItem: { item: i } };
    });
}

// ============================================================
// Daten-Assembler: Bereitet Spiele für Calendar + Sheets vor
// ============================================================

const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
    const j = items[i].json;
    results.push({
        json: {
            match_id: j.match_id || "",
            mein_team: j.mein_team || "",
            spieler_name: j.spieler_name || "",
            wettbewerb: j.wettbewerb || "",
            gegner: j.gegner || "",
            titel: j.titel || "",
            datum: j.datum || "",
            uhrzeit: j.uhrzeit || "",
            start_isogoogle: j.start_isogoogle || "",
            ortsangabe: j.ortsangabe || "",
            stadion_adresse: j.stadion_adresse || "",
            keine_spiele: j.keine_spiele || false
        },
        pairedItem: { item: i }
    });
}

return results;

// ============================================================
// Cross-Player Dedup: Prüft ob Spiel schon von anderem Spieler
// in diesem Durchlauf erstellt wurde.
// ============================================================

const spiele = $("Daten aufbereiten").all();
const alleSpiele = $("Alle Spiele lesen").all().filter(r => r.json && r.json.match_id);
const results = [];

for (const spielItem of spiele) {
    const s = spielItem.json;
    const matchId = String(s.match_id || "");
    if (!matchId || matchId === "SKIP" || matchId === "ERROR") continue;

    let found = null;
    for (const row of alleSpiele) {
        if (String(row.json.match_id) === matchId) {
            found = row.json;
            break;
        }
    }

    if (found && found.google_event_id) {
        let alteSpieler = found.spieler_namen || "";
        let spielerListe = alteSpieler ? alteSpieler.split(", ").filter(x => x.trim()) : [];
        if (!spielerListe.includes(s.spieler_name)) {
            spielerListe.push(s.spieler_name);
        }
        results.push({
            json: {
                ...s,
                is_duplicate: true,
                existing_event_id: found.google_event_id,
                alle_spieler: spielerListe.join(", ")
            }
        });
    } else {
        results.push({
            json: {
                ...s,
                is_duplicate: false,
                existing_event_id: "",
                alle_spieler: s.spieler_name
            }
        });
    }
}

if (results.length === 0) {
    return [{ json: { is_duplicate: false, match_id: "SKIP", keine_spiele: true } }];
}

return results;

// ============================================================
// fussball.de Spielplan Parser v6 (Cleanup & Recreate)
// ============================================================

try {
    const results = [];
    const heute = new Date();
    heute.setHours(0, 0, 0, 0);
    const limitDatum = new Date();
    limitDatum.setDate(heute.getDate() + 60);
    limitDatum.setHours(23, 59, 59, 999);
    const inputItems = $input.all();

    let meinTeam = "Unbekannt";
    let spielerName = "Unbekannt";
    let altersklasse = "";
    try {
        const loopData = $("Loop Over Items").item.json;
        meinTeam = loopData.team_name || "Unbekannt";
        spielerName = loopData.player_name || "Unbekannt";
        altersklasse = (loopData.team_altersklasse || "").trim();
    } catch (e) {}

    function normalizeTeam(name) {
        return name.toLowerCase()
            .replace(/\u00e4/g, 'ae').replace(/\u00f6/g, 'oe')
            .replace(/\u00fc/g, 'ue').replace(/\u00df/g, 'ss')
            .replace(/[^a-z0-9]/g, '');
    }

    function stripReserveSuffix(norm) {
        const suffixes = ['u23','u21','u19','u17','u16','iii','ii','iv'];
        for (const s of suffixes) {
            if (norm.endsWith(s)) return norm.slice(0, -s.length);
        }
        return norm;
    }

    function teamsMatch(a, b) {
        const na = normalizeTeam(a);
        const nb = normalizeTeam(b);
        if (na === nb) return true;
        if (na.length >= 6 && nb.length >= 6) {
            if (na.includes(nb) || nb.includes(na)) return true;
        }
        const ba = stripReserveSuffix(na);
        const bb = stripReserveSuffix(nb);
        if (ba && bb && ba.length >= 6 && bb.length >= 6) {
            if (ba === bb || ba.includes(bb) || bb.includes(ba)) return true;
        }
        return false;
    }

    function addAltersklasse(name, ak) {
        if (!ak) return name;
        if (name.toUpperCase().includes(ak.toUpperCase())) return name;
        return name + " " + ak;
    }

    for (let i = 0; i < inputItems.length; i++) {
        const item = inputItems[i].json;
        let html = item.data || item.body || "";
        if (!html) continue;
        html = html.replace(/<script[\s\S]*?<\/script>/gi, '');
        html = html.replace(/<!--[\s\S]*?-->/g, '');
        const rows = html.match(/<tr[^>]*>[\s\S]*?<\/tr>/gi) || [];

        let currentTag = "";
        let currentMonat = "";
        let currentJahr = "";
        let currentUhrzeit = "";
        let currentWettbewerb = "";
        let currentMatchNumId = "";

        for (const row of rows) {
            if (row.includes('row-headline') && row.includes('visible-small')) {
                const hlMatch = row.match(/(\d{2})\.(\d{2})\.(\d{4})\s*-\s*(\d{2}):(\d{2})\s*Uhr\s*\|\s*(.+?)\s*</);
                if (hlMatch) {
                    currentTag = hlMatch[1];
                    currentMonat = hlMatch[2];
                    currentJahr = hlMatch[3];
                    currentUhrzeit = hlMatch[4] + ":" + hlMatch[5];
                    currentWettbewerb = hlMatch[6].replace(/<[^>]*>/g, '').trim();
                }
                continue;
            }
            if (row.includes('row-competition')) {
                const dateMatch = row.match(/(\d{2})\.(\d{2})\.(\d{2,4})\s*\|/);
                if (dateMatch) {
                    currentTag = dateMatch[1];
                    currentMonat = dateMatch[2];
                    currentJahr = dateMatch[3];
                    if (currentJahr.length === 2) currentJahr = "20" + currentJahr;
                }
                const timeMatch = row.match(/(?:\||&nbsp;)\s*(\d{2}):(\d{2})\s*</);
                if (timeMatch) {
                    currentUhrzeit = timeMatch[1] + ":" + timeMatch[2];
                } else {
                    const timeFB = row.match(/(\d{2}):(\d{2})/);
                    if (timeFB) currentUhrzeit = timeFB[1] + ":" + timeFB[2];
                }
                const compMatch = row.match(/column-team[\s\S]*?<a[^>]*>([\s\S]*?)<\/a>/i);
                if (compMatch) {
                    currentWettbewerb = compMatch[1].replace(/<[^>]*>/g, '').trim();
                }
                const matchNumMatch = row.match(/(\d{9,})/);
                if (matchNumMatch) currentMatchNumId = matchNumMatch[1];
                continue;
            }
            if (!row.includes('column-club')) continue;
            if (!row.includes('column-colon')) continue;
            if (!currentTag || !currentMonat || !currentJahr || !currentUhrzeit) continue;

            const spielDatum = new Date(parseInt(currentJahr), parseInt(currentMonat) - 1, parseInt(currentTag));
            if (spielDatum < heute || spielDatum > limitDatum) continue;

            const clubCells = row.match(/<td[^>]*class="[^"]*column-club[^"]*"[^>]*>[\s\S]*?<\/td>/gi) || [];
            let heimTeam = "";
            let gastTeam = "";
            if (clubCells.length >= 2) {
                const nameRegex = /<div[^>]*class="[^"]*club-name[^"]*"[^>]*>\s*([\s\S]*?)\s*<\/div>/i;
                const heimMatch = clubCells[0].match(nameRegex);
                const gastMatch = clubCells[1].match(nameRegex);
                if (heimMatch) heimTeam = heimMatch[1].replace(/<[^>]*>/g, '').trim();
                if (gastMatch) gastTeam = gastMatch[1].replace(/<[^>]*>/g, '').trim();
            }
            if (!heimTeam || !gastTeam) {
                const altMatches = [...row.matchAll(/data-alt="([^"]+)"/gi)];
                if (altMatches.length >= 2) {
                    if (!heimTeam) heimTeam = altMatches[0][1];
                    if (!gastTeam) gastTeam = altMatches[1][1];
                }
            }
            if (!heimTeam || !gastTeam) continue;
            if (!teamsMatch(heimTeam, meinTeam) && !teamsMatch(gastTeam, meinTeam)) continue;

            let ortsangabe = "";
            const detailMatch = row.match(/<td[^>]*class="[^"]*column-detail[^"]*"[^>]*>[\s\S]*?href="([^"]+)"/i);
            if (detailMatch) ortsangabe = detailMatch[1];
            if (!ortsangabe) {
                const scoreMatch = row.match(/<td[^>]*class="[^"]*column-score[^"]*"[^>]*>[\s\S]*?href="([^"]+)"/i);
                if (scoreMatch) ortsangabe = scoreMatch[1];
            }
            if (!ortsangabe) {
                const anySpielLink = row.match(/href="([^"]*\/spiel\/[^"]+)"/i);
                if (anySpielLink) ortsangabe = anySpielLink[1];
            }
            if (ortsangabe && ortsangabe.startsWith('/')) ortsangabe = "https://www.fussball.de" + ortsangabe;

            const heimTeamDisplay = addAltersklasse(heimTeam, altersklasse);
            const gastTeamDisplay = addAltersklasse(gastTeam, altersklasse);
            let wettbewerbDisplay = currentWettbewerb || "Spiel";
            if (altersklasse && !wettbewerbDisplay.toUpperCase().includes(altersklasse.toUpperCase())) {
                wettbewerbDisplay = altersklasse + " " + wettbewerbDisplay;
            }
            const gegner = teamsMatch(heimTeam, meinTeam) ? gastTeamDisplay : heimTeamDisplay;
            const matchId = currentMatchNumId || ("fde_" + normalizeTeam(heimTeam).substring(0,12) + "_" + normalizeTeam(gastTeam).substring(0,12) + "_" + normalizeTeam(currentWettbewerb).substring(0,8));
            const start_isogoogle = currentJahr + "-" + currentMonat + "-" + currentTag + "T" + currentUhrzeit + ":00";
            const datumKey = currentTag + "." + currentMonat + "." + currentJahr;

            results.push({
                json: {
                    match_id: matchId, mein_team: meinTeam, spieler_name: spielerName,
                    wettbewerb: wettbewerbDisplay, gegner: gegner,
                    titel: heimTeamDisplay + " - " + gastTeamDisplay,
                    datum: datumKey, uhrzeit: currentUhrzeit,
                    start_isogoogle: start_isogoogle, ortsangabe: ortsangabe,
                    keine_spiele: false
                },
                pairedItem: { item: 0 }
            });
            currentMatchNumId = "";
        }
    }

    if (results.length === 0) {
        return [{ json: { match_id: "SKIP", mein_team: meinTeam, spieler_name: spielerName, wettbewerb: "", gegner: "", titel: "", datum: "", uhrzeit: "", start_isogoogle: "", ortsangabe: "", keine_spiele: true }, pairedItem: { item: 0 } }];
    }
    return results;

} catch (error) {
    return [{ json: { match_id: "ERROR", mein_team: "Fehler", spieler_name: "Fehler", wettbewerb: "", gegner: "", titel: "", datum: "", uhrzeit: "", start_isogoogle: "", ortsangabe: "", keine_spiele: true, error_message: error.message }, pairedItem: { item: 0 } }];
}
